  arrays.forEach(k=>{if(!Array.isArray(state[k]))state[k]=[]});
  state.paritySettings={bookingNoShowGraceMinutes:10,bookingGuardMinutes:15,bookingTurnoverMinutes:5,groupDiscountPercent:5,passValidityDays:90,pointsPerGameDirham:1,pointsPerSnackDirham:.5,pointsForOneDirham:20,maxRedeemPercent:20,tournamentDefaultEntry:20,tournamentCheckInMinutes:20,kingEntryFee:7,kingMaxConsecutiveWins:3,kingMaxReignMinutes:45,kingTransitionMinutes:2,consentTextVersion:'MEDIA-2026-01',consentRetentionDays:1825,ownerDisplayName:'Propriétaire LA PAUSE CLUB',...(state.paritySettings||{})};
