function renderQueueV15(){
  ensureV15ParityState();const waiting=state.queue.filter(q=>!['LEFT','SEATED'].includes(String(q.status||'WAITING').toUpperCase())).sort((a,b)=>(a.joinedAt||0)-(b.joinedAt||0));
  let html=pageTitle('File d’attente','Préférence PS5/SIM, taille du groupe, estimation, appel et placement.',`<button class="primary orange-btn compact-btn" id="queueAddV15">＋ Ajouter</button>`);
  html+=v15Metrics([{label:'En attente',value:waiting.length},{label:'PS5 libres',value:state.stations.filter(s=>s.enabled&&s.type==='PS5'&&!activeSessionFor(s.id)).length},{label:'SIM VIP libre',value:state.stations.some(s=>s.enabled&&s.type==='SIM'&&!activeSessionFor(s.id))?'OUI':'NON'},{label:'Attente estimée',value:waiting.length?`${Math.max(...waiting.map(q=>num(q.estimatedMinutes,0)))} min`:'0 min'}]);
  html+=waiting.length?`<div class="v15-grid one">${waiting.map((q,i)=>`<div class="v15-card"><div class="v15-row"><div class="v15-queue-rank">${i+1}</div><div class="main"><b>${esc(q.customerName||'Client')}</b><small>${esc(q.requestedKind||'ANY')} · ${q.partySize||1} joueur(s) · arrivé ${fmtTime(q.joinedAt||now())}</small></div>${statusV15(q.status||'WAITING')}</div><div class="v15-product-meta"><span>Estimation</span><b>${num(q.estimatedMinutes,0)} min</b></div><div class="v15-actions">${String(q.status||'WAITING').toUpperCase()==='WAITING'?`<button class="secondary compact-btn" data-q-call-v15="${q.id}">Appeler</button>`:''}<button class="primary compact-btn" data-q-seat-v15="${q.id}">Placer</button><button class="ghost compact-btn" data-q-left-v15="${q.id}">Parti</button></div></div>`).join('')}</div>`:'<div class="empty"><b>File vide</b>Aucun joueur en attente.</div>';
  $('view').innerHTML=html;$('queueAddV15').onclick=openQueueV15;
  document.querySelectorAll('[data-q-call-v15]').forEach(b=>b.onclick=()=>{const q=state.queue.find(x=>x.id===b.dataset.qCallV15);q.status='CALLED';q.calledAt=now();auditV15('QUEUE_CALLED',q.customerName,q.requestedKind);saveState({eventType:'queue.called',entityId:q.id});renderQueueV15()});
  document.querySelectorAll('[data-q-left-v15]').forEach(b=>b.onclick=()=>{const q=state.queue.find(x=>x.id===b.dataset.qLeftV15);q.status='LEFT';q.leftAt=now();auditV15('QUEUE_LEFT',q.customerName,'Sortie file');saveState({eventType:'queue.left',entityId:q.id});renderQueueV15()});
  document.querySelectorAll('[data-q-seat-v15]').forEach(b=>b.onclick=()=>seatQueueV15(b.dataset.qSeatV15));
}
function queueEstimateV15(kind){
  const matching=state.stations.filter(s=>s.enabled&&(kind==='ANY'||(kind==='SIMULATOR'?s.type==='SIM':s.type==='PS5')));
  if(matching.some(s=>!activeSessionFor(s.id)))return 0;
  const ends=matching.map(s=>activeSessionFor(s.id)).filter(Boolean).map(s=>s.endAt||now()+state.sessionRules.defaultDuration*60000);return Math.max(5,Math.ceil((Math.min(...ends)-now())/60000));
}
function openQueueV15(){
  showModal(`<h3>Ajouter à la file</h3><div class="field"><label>Client enregistré</label><select id="qClientV15"><option value="">Passage</option>${state.clients.filter(c=>c.status==='ACTIVE').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Nom *</label><input id="qNameV15"></div><div class="grid-2"><div class="field"><label>Préférence</label><select id="qKindV15"><option value="ANY">N’importe quel poste</option><option value="PS5">PS5</option><option value="SIMULATOR">SIM RACING VIP</option></select></div><div class="field"><label>Groupe</label><input id="qPartyV15" type="number" min="1" max="12" value="1"></div></div><div class="modal-actions"><button class="ghost" id="modalCancel">Retour</button><button class="primary" id="modalOk">Ajouter</button></div>`);$('modalCancel').onclick=closeModal;$('qClientV15').onchange=()=>{const c=clientV15($('qClientV15').value);if(c)$('qNameV15').value=c.name};$('modalOk').onclick=()=>{const name=$('qNameV15').value.trim();if(!name)return toast('Nom obligatoire');const kind=$('qKindV15').value,q={id:uid('queue'),customerId:$('qClientV15').value||null,customerName:name,requestedKind:kind,partySize:clamp(num($('qPartyV15').value,1),1,12),joinedAt:now(),estimatedMinutes:queueEstimateV15(kind),status:'WAITING'};state.queue.push(q);auditV15('QUEUE_ADD',name,`${kind} · ${q.estimatedMinutes} min`);saveState({eventType:'queue.added',entityId:q.id,payload:q});closeModal();renderQueueV15();toast('Ajouté à la file')}}
function seatQueueV15(id){
  const q=state.queue.find(x=>x.id===id);if(!q)return;const free=state.stations.filter(s=>s.enabled&&!activeSessionFor(s.id)&&(q.requestedKind==='ANY'||(q.requestedKind==='SIMULATOR'?s.type==='SIM':s.type==='PS5')));if(!free.length)return toast('Aucun poste compatible disponible');
  q.status='SEATED';q.seatedAt=now();auditV15('QUEUE_SEATED',q.customerName,free[0].name);saveState({eventType:'queue.seated',entityId:q.id});selectedStationId=free[0].id;openStation(free[0].id);if(sheetDraft){sheetDraft.customerId=q.customerId||'';sheetDraft.clientQuery=q.customerName}
}


