  if(mode==='king')html+=kingListV15();else if(mode==='challenges')html+=challengesListV15();else html+=tournamentsListV15();
  $('view').innerHTML=html;document.querySelectorAll('[data-v15-tab]').forEach(b=>b.onclick=()=>{const m=b.dataset.v15Tab;currentView=m==='king'?'hall':m;renderCompetitionsV15(m)});
  if($('tourAddV15'))$('tourAddV15').onclick=()=>openTournamentV15();if($('challengeAddV15'))$('challengeAddV15').onclick=()=>openChallengeV15();if($('kingAddV15'))$('kingAddV15').onclick=()=>openKingV15();
