function generateTournamentMatchesV15(t){
  const players=t.participants.filter(p=>p.checkedIn||p.status==='CHECKED_IN');if(players.length<2)return toast('Au moins 2 joueurs check-in');t.matches=[];let round=1;
  if(t.format==='ROUND_ROBIN'){for(let i=0;i<players.length;i++)for(let j=i+1;j<players.length;j++)t.matches.push({id:uid('tm'),round,label:`${players[i].name} vs ${players[j].name}`,playerOneId:players[i].id,playerTwoId:players[j].id,bestOf:t.bestOf,status:'SCHEDULED',disputeStatus:'NONE'})}
  else {for(let i=0;i<players.length;i+=2){const a=players[i],b=players[i+1];t.matches.push({id:uid('tm'),round,label:`Match ${t.matches.length+1}`,playerOneId:a.id,playerTwoId:b?.id,bestOf:t.bestOf,status:b?'SCHEDULED':'CONFIRMED',winnerParticipantId:b?undefined:a.id,disputeStatus:'NONE'})}}
  t.stage='qualifiers';t.status='LIVE';auditV15('TOURNAMENT_START',t.name,`${t.format} · ${players.length} joueurs`);saveState({eventType:'tournament.started',entityId:t.id,payload:{format:t.format}});closeModal();openTournamentDetailV15(t)
}
function openMatchV15(t,m){
  if(!m)return;const a=t.participants.find(p=>p.id===m.playerOneId),b=t.participants.find(p=>p.id===m.playerTwoId),max=Math.ceil(m.bestOf/2);
  showModal(`<h3>${esc(m.label)}</h3><p>${esc(a?.name||'BYE')} vs ${esc(b?.name||'BYE')} · BO${m.bestOf}</p><div class="grid-2"><div class="field"><label>${esc(a?.name||'A')}</label><input id="mScoreA15" type="number" min="0" max="${max}" value="${m.scoreOne??0}"></div><div class="field"><label>${esc(b?.name||'B')}</label><input id="mScoreB15" type="number" min="0" max="${max}" value="${m.scoreTwo??0}"></div></div><div class="field"><label>Preuve / note résultat</label><textarea id="mEvidence15" rows="2">${esc(m.evidenceNote||'')}</textarea></div>${m.disputeStatus==='OPEN'?`<div class="v15-danger-note"><b>Litige ouvert</b><br>${esc(m.disputeNote||'')}</div>`:''}<div class="field"><label>Note litige / arbitrage</label><input id="mDispute15" value="${esc(m.disputeNote||'')}"></div><div class="v15-actions">${m.status==='SCHEDULED'?'<button class="secondary" id="mCall15">Appeler</button>':''}${['SCHEDULED','CALLED','LIVE','REVIEW'].includes(m.status)?'<button class="primary" id="mReport15">Reporter résultat</button>':''}${m.disputeStatus!=='OPEN'&&m.status!=='CONFIRMED'?'<button class="danger" id="mOpenDispute15">Ouvrir litige</button>':''}${m.disputeStatus==='OPEN'?'<button class="secondary" id="mResolve15">Résoudre</button>':''}${m.status==='REVIEW'&&m.disputeStatus!=='OPEN'?'<button class="primary" id="mConfirm15">Confirmer manager</button>':''}</div><button class="ghost full" id="modalCancel">Retour tournoi</button>`);$('modalCancel').onclick=()=>{closeModal();openTournamentDetailV15(t)};
  if($('mCall15'))$('mCall15').onclick=()=>{m.status='CALLED';m.calledAt=isoV15();auditV15('TOURNAMENT_MATCH_CALL',t.name,m.label);saveState({eventType:'tournament.match_called',entityId:m.id});closeModal();openMatchV15(t,m)};
  if($('mReport15'))$('mReport15').onclick=()=>{const sa=num($('mScoreA15').value),sb=num($('mScoreB15').value);if(sa===sb)return toast('Le score doit désigner un gagnant');m.scoreOne=sa;m.scoreTwo=sb;m.winnerParticipantId=sa>sb?a?.id:b?.id;m.evidenceNote=$('mEvidence15').value.trim();m.reportedBy='Android';m.status='REVIEW';m.endedAt=isoV15();auditV15('TOURNAMENT_MATCH_REPORT',t.name,`${m.label} · ${sa}-${sb}`);saveState({eventType:'tournament.match_reported',entityId:m.id,payload:m});closeModal();openMatchV15(t,m)};
  if($('mOpenDispute15'))$('mOpenDispute15').onclick=()=>{const note=$('mDispute15').value.trim();if(!note)return toast('Motif du litige obligatoire');m.disputeStatus='OPEN';m.disputeNote=note;auditV15('TOURNAMENT_MATCH_DISPUTE',t.name,`${m.label} · ${note}`,'WARNING');saveState({eventType:'tournament.match_disputed',entityId:m.id});closeModal();openMatchV15(t,m)};
  if($('mResolve15'))$('mResolve15').onclick=()=>{const note=$('mDispute15').value.trim();if(!note)return toast('Décision d’arbitrage obligatoire');m.disputeStatus='RESOLVED';m.disputeNote=note;m.status='REVIEW';auditV15('TOURNAMENT_MATCH_RESOLVE',t.name,`${m.label} · ${note}`);saveState({eventType:'tournament.match_resolved',entityId:m.id});closeModal();openMatchV15(t,m)};
  if($('mConfirm15'))$('mConfirm15').onclick=()=>confirmMatchV15(t,m);
}
function confirmMatchV15(t,m){
  if(!m.winnerParticipantId)return toast('Aucun gagnant reporté');m.status='CONFIRMED';m.confirmedBy='Manager Android';const w=t.participants.find(p=>p.id===m.winnerParticipantId),l=t.participants.find(p=>p.id===(m.winnerParticipantId===m.playerOneId?m.playerTwoId:m.playerOneId));if(w)w.wins=num(w.wins)+1;if(l)l.losses=num(l.losses)+1;auditV15('TOURNAMENT_MATCH_CONFIRM',t.name,`${m.label} · ${w?.name||'gagnant'}`);saveState({eventType:'tournament.match_confirmed',entityId:m.id,payload:m});closeModal();openTournamentDetailV15(t)
}
function advanceTournamentV15(t){
  if(t.matches.some(m=>m.status!=='CONFIRMED'))return toast('Tous les matchs doivent être confirmés ou arbitrés');
  let winners=[];
  if(t.format==='ROUND_ROBIN'){const ranked=t.participants.filter(p=>p.checkedIn).slice().sort((a,b)=>num(b.wins)-num(a.wins)||num(a.losses)-num(b.losses));if(ranked.length<2)return;winners=ranked.slice(0,2).map(p=>p.id)}
  else winners=t.matches.map(m=>m.winnerParticipantId).filter(Boolean);
  const uniq=[...new Set(winners)];if(uniq.length===1)return finishTournamentV15(t,uniq[0]);
  if(uniq.length===2&&t.stage!=='final'){const round=Math.max(0,...t.matches.map(m=>m.round||1))+1;t.matches=[{id:uid('tm'),round,label:'FINALE',playerOneId:uniq[0],playerTwoId:uniq[1],bestOf:Math.max(3,t.bestOf),status:'SCHEDULED',disputeStatus:'NONE'}];t.stage='final';auditV15('TOURNAMENT_STAGE',t.name,'FINALE');saveState({eventType:'tournament.final',entityId:t.id});closeModal();openTournamentDetailV15(t);return}
  if(t.stage==='final'&&uniq.length===1)return finishTournamentV15(t,uniq[0]);
  const round=Math.max(0,...t.matches.map(m=>m.round||1))+1,next=[];for(let i=0;i<uniq.length;i+=2){const a=uniq[i],b=uniq[i+1];next.push({id:uid('tm'),round,label:`Match ${i/2+1}`,playerOneId:a,playerTwoId:b,bestOf:t.bestOf,status:b?'SCHEDULED':'CONFIRMED',winnerParticipantId:b?undefined:a,disputeStatus:'NONE'})}t.matches=next;t.stage=uniq.length<=4?'semifinals':'knockout';auditV15('TOURNAMENT_STAGE',t.name,tourStageNameV15(t));saveState({eventType:'tournament.round',entityId:t.id});closeModal();openTournamentDetailV15(t)
}
function finishTournamentV15(t,pid){const p=t.participants.find(x=>x.id===pid);if(!p)return;p.status='WINNER';t.winner={id:p.id,name:p.name,at:now()};t.stage='finished';t.status='COMPLETED';auditV15('TOURNAMENT_WINNER',t.name,p.name);saveState({eventType:'tournament.completed',entityId:t.id,payload:{winner:t.winner}});closeModal();openTournamentDetailV15(t)}

/* Challenges: keep Android periodic leaderboard and add Web paid participation/status. */
function normalizeChallengeV15(ch){
  ch.name=ch.name||ch.title||'Challenge';ch.title=ch.title||ch.name;ch.entries=Array.isArray(ch.entries)?ch.entries:[];ch.participants=Array.isArray(ch.participants)?ch.participants:[];ch.period=ch.period||'HEBDOMADAIRE';ch.format=ch.format||'TIME_ATTACK';ch.entryFeeCents=num(ch.entryFeeCents,centsV15(ch.entryFee||0));ch.entryFee=dhV15(ch.entryFeeCents);ch.capacity=num(ch.capacity,16);ch.stage=ch.stage||(ch.status==='COMPLETED'||ch.status==='TERMINÉ'?'finished':'active');ch.status=ch.status||'OPEN';return ch
}
function challengesListV15(){
  state.challenges.forEach(normalizeChallengeV15);return `<div class="page-actions" style="margin-bottom:12px"><button class="primary orange-btn compact-btn" id="challengeAddV15">＋ Challenge</button></div>${state.challenges.length?`<div class="v15-grid">${state.challenges.map(ch=>{const rank=v14ChallengeRank(ch),winner=ch.winner||rank[0];return `<div class="v15-card clickable" data-ch-v15="${ch.id}"><div class="v15-card-head"><div><h3>${esc(ch.name)}</h3><p>${esc(ch.game||'—')} · ${esc(ch.format)} · ${esc(ch.period)}</p></div>${statusV15(ch.stage==='finished'?'COMPLETED':ch.status)}</div>${ch.stage==='finished'&&winner?`<div class="v15-winner"><span class="cup">🏆</span><small>GAGNANT</small><strong>${esc(winner.name||winner.customerName)}</strong></div>`:''}<div class="v15-chiprow"><span class="v15-chip">${ch.participants.length} participants</span><span class="v15-chip">${ch.entries.length} résultats</span><span class="v15-chip">${fmtMoney(dhV15(ch.entryFeeCents))}</span></div></div>`}).join('')}</div>`:'<div class="empty">Aucun challenge.</div>'}`
}
function openChallengeV15(ch=null){
  ch=ch?normalizeChallengeV15(ch):null;showModal(`<h3>${ch?'Modifier':'Créer'} challenge</h3><div class="field"><label>Nom</label><input id="chName15" value="${esc(ch?.name||'')}"></div><div class="grid-2"><div class="field"><label>Jeu</label><input id="chGame15" value="${esc(ch?.game||'EA SPORTS FC')}"></div><div class="field"><label>Format</label><select id="chFormat15">${['DUEL','BEST_OF_3','TIME_ATTACK','COOP_SCORE'].map(x=>`<option ${ch?.format===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="grid-2"><div class="field"><label>Période</label><select id="chPeriod15">${['PONCTUEL','QUOTIDIEN','HEBDOMADAIRE','MENSUEL','PERMANENT'].map(x=>`<option ${ch?.period===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Niveau</label><select id="chLevel15">${['OUVERT','INTERMEDIAIRE','EXPERT'].map(x=>`<option ${ch?.level===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="grid-2"><div class="field"><label>Capacité</label><input id="chCap15" type="number" min="2" value="${ch?.capacity||16}"></div><div class="field"><label>Entrée · DH</label><input id="chFee15" type="number" min="0" step=".5" value="${dhV15(ch?.entryFeeCents||0)}"></div></div><div class="field"><label>Objectif / règle de score</label><input id="chTarget15" value="${esc(ch?.target||ch?.callout||'Meilleur score')}"></div><div class="field"><label>Récompense</label><input id="chReward15" value="${esc(ch?.reward||ch?.rewardLabel||'')}"></div><div class="modal-actions"><button class="ghost" id="modalCancel">Retour</button><button class="primary" id="modalOk">Enregistrer</button></div>`);$('modalCancel').onclick=closeModal;$('modalOk').onclick=()=>{const name=$('chName15').value.trim();if(!name)return toast('Nom obligatoire');const x=ch||{id:uid('challenge'),entries:[],participants:[],createdAt:isoV15(),stage:'active',status:'OPEN'};Object.assign(x,{name,title:name,game:$('chGame15').value.trim(),format:$('chFormat15').value,period:$('chPeriod15').value,level:$('chLevel15').value,capacity:num($('chCap15').value,16),entryFeeCents:centsV15($('chFee15').value),entryFee:num($('chFee15').value),target:$('chTarget15').value.trim(),callout:$('chTarget15').value.trim(),reward:$('chReward15').value.trim(),rewardLabel:$('chReward15').value.trim()});if(!ch)state.challenges.push(x);auditV15(ch?'CHALLENGE_UPDATE':'CHALLENGE_CREATE',x.name,`${x.period} · ${x.format}`);saveState({eventType:ch?'challenge.updated':'challenge.created',entityId:x.id,payload:x});closeModal();renderCompetitionsV15('challenges')}}
