function venueResumeAllV15(){
  const paused=state.sessions.filter(s=>s.status==='paused'),t=now();
  paused.forEach(s=>{const delta=Math.max(0,t-num(s.pausedAt,t));s.pauseTotalMs=num(s.pauseTotalMs)+delta;if(s.endAt)s.endAt+=delta;s.pausedAt=null;s.status='active';s.updatedAt=t;s.revision=num(s.revision)+1;scheduleAlarm(s)});
  auditV15('VENUE_RESUME_ALL','Salle',`${paused.length} session(s) reprise(s)`);
  saveState({eventType:'venue.resume_all',payload:{sessionIds:paused.map(s=>s.id),at:t}});renderView();toast(`${paused.length} session(s) reprise(s)`);
}

